import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../../../spec/expression-reference.json");
const outFile = resolve(here, "../src/generated/expression-reference.ts");

const reference = JSON.parse(await readFile(source, "utf-8"));

await mkdir(dirname(outFile), { recursive: true });
await writeFile(
	outFile,
	[
		"// Generated by scripts/bundle-reference.mjs from spec/expression-reference.json. Do not edit.",
		`export const EXPRESSION_REFERENCE_SOURCE = ${JSON.stringify(JSON.stringify(reference))};`,
		"",
	].join("\n"),
);
